mapper.select:
select FIN_CASH_PAY_RULE.PAY_TYPE payType,
	   FIN_CASH_PAY_RULE.PAY_CYCLE payCycle,
	   FIN_CASH_PAY_RULE.PAY_CYCLE_VAL payCycleVal,
	   FIN_CASH_PAY_RULE.END_TDAY_RULE endTdayRule,
	   FIN_CASH_PAY_RULE.PAY_TDAY_RULE payTdayRule,
	   FIN_CASH_PAY_RULE.CALC_RULE calcRule,
	   FIN_CASH_PAY_RULE.FIRST_PAY_DATE firstPayDate
  from FIN_CASH_INFO, FIN_CASH_PAY_RULE, FIN_PRODUCT
 where FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
   and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
   and FIN_CASH_INFO.FINPROD_ID = #{finprodId}
   and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType} 
   and FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID
   and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
   and FIN_CASH_PAY_RULE.FINPROD_ID = #{finprodId}

   		and FIN_CASH_PAY_RULE.EFF_DATE = to_date(#{effDate},'yyyy-MM-dd')
